const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dc = ee.Geometry.Point([-77.0369, 38.9072]).buffer(5000); // Washington D.C. with buffer

  // 2. Data Acquisition
  const modisJan = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate('2019-01-29', '2019-01-30')
    .filterBounds(dc);

  const modisFeb = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate('2019-02-05', '2019-02-06')
    .filterBounds(dc);

  // Check for empty collections
  const janCount = modisJan.size().getInfo();
  const febCount = modisFeb.size().getInfo();

  console.log(`Jan 29 Images: ${janCount}, Feb 5 Images: ${febCount}`);

  if (janCount === 0 || febCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const janImg = modisJan.first();
  const febImg = modisFeb.first();

  // Convert LST from Kelvin to Celsius (scale 0.02 for MODIS)
  const janTemp = janImg.select('LST_Day_1km').multiply(0.02).subtract(273.15);
  const febTemp = febImg.select('LST_Day_1km').multiply(0.02).subtract(273.15);

  // 3. Check valid pixels
  const janCountPixels = janTemp.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dc,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const febCountPixels = febTemp.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dc,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`Jan valid pixels: ${janCountPixels}, Feb valid pixels: ${febCountPixels}`);

  if (janCountPixels === 0 || febCountPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculate temperatures
  const janMean = janTemp.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dc,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const febMean = febTemp.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dc,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`Jan 29 Temp: ${janMean.toFixed(1)}°C, Feb 5 Temp: ${febMean.toFixed(1)}°C`);

  // 5. Validation & Final Answer
  if (janMean === null || febMean === null || isNaN(janMean) || isNaN(febMean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  const diff = Math.abs(janMean - febMean);
  console.log(`Temperature difference: ${diff.toFixed(1)}°C`);

  if (diff >= 24) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
